xml.Script:
        Colors[0] := '0055EE'; // Blue
        Colors[1] := 'AA00CC'; // Violett
        Colors[2] := 'EE0000'; // Red
        Colors[3] := 'FF800A'; // Orange
        Colors[4] := 'FFBB00'; //
        Colors[5] := 'FFFF00'; // Yellow
        Colors[6] := 'AAFF00'; //
        Colors[7] := '00DD00'; // LightGreen

        R := 0.5;
        H := R;
        D := R / sqrt(6);

        N := 64;
        N8 := N div 8;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2*Pi / N * i);
            y[i] := R * sin(2*Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
